        let tmp = TempDir::new().unwrap();
        let crate_dir = tmp.path().join("crate");
        fs::create_dir(&crate_dir).unwrap();

        let result = find_tspecs(&crate_dir, &[]);
        assert!(result.is_err());
        assert!(
            result
                .unwrap_err()
                .to_string()
                .contains("no tspec files found")
        );
    }

