     1→//! `cargo xt ts list` - List tspec files
     2→
     3→use anyhow::Result;
     4→use std::path::Path;
     5→
     6→use crate::TSPEC_SUFFIX;
     7→use crate::find_paths::{find_workspace_root, get_crate_name, resolve_package_dir};
     8→use crate::workspace::WorkspaceInfo;
     9→
    10→/// List all tspec files in workspace or for a specific package
    11→pub fn list_tspecs(package: Option<&str>) -> Result<()> {
    12→    let workspace = find_workspace_root()?;
    13→
    14→    // Check if we're in a package directory (has Cargo.toml in cwd)
    15→    let cwd = std::env::current_dir()?;
    16→    let in_package_dir = cwd.join("Cargo.toml").exists();
    17→
    18→    match (package, in_package_dir) {
    19→        (Some(name), _) => {
    20→            // Explicit package specified
    21→            let package_dir = resolve_package_dir(&workspace, Some(name))?;
    22→            let tspecs = find_tspec_files(&package_dir)?;
    23→            print_package_tspecs(name, &package_dir, &tspecs);
    24→        }
    25→        (None, true) => {
    26→            // In a package directory, list just this package
    27→            let package_dir = resolve_package_dir(&workspace, None)?;
    28→            let pkg_name = get_crate_name(&package_dir)?;
    29→            let tspecs = find_tspec_files(&package_dir)?;
    30→            print_package_tspecs(&pkg_name, &package_dir, &tspecs);
    31→        }
    32→        (None, false) => {
    33→            // At workspace root, list all packages
    34→            let info = WorkspaceInfo::discover()?;
    35→            let mut found_any = false;
    36→
    37→            for member in &info.members {
    38→                let tspecs = find_tspec_files(&member.path)?;
    39→                if !tspecs.is_empty() {
    40→                    print_package_tspecs(&member.name, &member.path, &tspecs);
    41→                    found_any = true;
    42→                }
    43→            }
    44→
    45→            if !found_any {
    46→                println!("No *{} files found in workspace", TSPEC_SUFFIX);
    47→            }
    48→        }
    49→    }
    50→
    51→    Ok(())
    52→}
    53→
    54→/// Find all tspec files (files ending with TSPEC_SUFFIX) in a directory
    55→pub(crate) fn find_tspec_files(dir: &Path) -> Result<Vec<String>> {
    56→    let mut files = Vec::new();
    57→
    58→    if let Ok(entries) = std::fs::read_dir(dir) {
    59→        for entry in entries.filter_map(|e| e.ok()) {
    60→            let name = entry.file_name().to_string_lossy().to_string();
    61→            if name.ends_with(TSPEC_SUFFIX) {
    62→                files.push(name);
    63→            }
    64→        }
    65→    }
    66→
    67→    files.sort();
    68→    Ok(files)
    69→}
    70→
    71→/// Print tspec files for a package
    72→fn print_package_tspecs(package_name: &str, package_dir: &Path, tspecs: &[String]) {
    73→    println!("{}:", package_name);
    74→    for tspec in tspecs {
    75→        let path = package_dir.join(tspec);
    76→        let size = std::fs::metadata(&path)
    77→            .map(|m| format_size(m.len()))
    78→            .unwrap_or_else(|_| "?".to_string());
    79→        println!("  {} ({})", tspec, size);
    80→    }
    81→}
    82→
    83→/// Format file size in human-readable form
    84→pub(crate) fn format_size(bytes: u64) -> String {
    85→    if bytes < 1024 {
    86→        format!("{} B", bytes)
    87→    } else {
    88→        format!("{:.1} KB", bytes as f64 / 1024.0)
    89→    }
    90→}
    91→
    92→#[cfg(test)]
    93→mod tests {
    94→    use super::*;
    95→    use crate::test_constants::SUFFIX;
    96→    use tempfile::TempDir;
    97→
    98→    #[test]
    99→    fn format_size_bytes() {
   100→        assert_eq!(format_size(100), "100 B");
   101→        assert_eq!(format_size(1023), "1023 B");
   102→    }
   103→
